-- Run 1st in Supabase SQL Editor
create extension if not exists pgcrypto;
create table site_settings(id uuid primary key default gen_random_uuid(),website_name text,website_logo text,favicon text,tamil_slogan text,default_seo_title text,default_seo_description text,social_image text,primary_color text default '#7654C5',secondary_color text default '#6040A8',updated_at timestamptz default now());
create table navigation_links(id uuid primary key default gen_random_uuid(),title text not null,url text not null,display_order int default 0,is_active bool default true,created_at timestamptz default now(),updated_at timestamptz default now());
create table homepage_sections(id uuid primary key default gen_random_uuid(),section_key text not null check(section_key in('hero','intro','services','why','articles','about','contact')),section_title text,section_description text,section_content jsonb default '{}',image_url text,display_order int default 0,is_active bool default true,created_at timestamptz default now(),updated_at timestamptz default now());
create table service_categories(id uuid primary key default gen_random_uuid(),title text not null,slug text unique not null,description text,image_url text,display_order int default 0,is_published bool default false,created_at timestamptz default now(),updated_at timestamptz default now());
create table service_subcategories(id uuid primary key default gen_random_uuid(),category_id uuid not null references service_categories(id) on delete cascade,title text not null,slug text not null,description text,display_order int default 0,is_published bool default false,created_at timestamptz default now(),updated_at timestamptz default now(),unique(category_id,slug));
create table service_content_blocks(id uuid primary key default gen_random_uuid(),category_id uuid not null references service_categories(id) on delete cascade,subcategory_id uuid not null references service_subcategories(id) on delete cascade,block_type text not null check(block_type in('heading','paragraph','article','image','image_text','gallery','video','multi_section','custom')),title text,content jsonb default '{}',image_url text,video_url text,display_order int default 0,status text default 'draft' check(status in('draft','published')),created_at timestamptz default now(),updated_at timestamptz default now());
create table guidance_categories(id uuid primary key default gen_random_uuid(),title text not null,slug text unique not null,description text,display_order int default 0,is_published bool default false,created_at timestamptz default now(),updated_at timestamptz default now());
create table guidance_articles(id uuid primary key default gen_random_uuid(),category_id uuid references guidance_categories(id) on delete set null,title text not null,slug text unique not null,short_description text,content text,featured_image text,seo_title text,seo_description text,is_featured bool default false,status text default 'draft' check(status in('draft','published')),published_at timestamptz,display_order int default 0,created_at timestamptz default now(),updated_at timestamptz default now());
create table about_sections(id uuid primary key default gen_random_uuid(),title text not null,title_en text,description text,description_en text,content jsonb default '{}',content_en jsonb default '{}',image_url text,display_order int default 0,status text default 'draft' check(status in('draft','published')),created_at timestamptz default now(),updated_at timestamptz default now());
create table counsellor_profiles(id uuid primary key default gen_random_uuid(),name text not null,name_en text,photo_url text,qualifications text not null,qualifications_en text,experience text not null,experience_en text,designation text,designation_en text,specialization text,specialization_en text,bio text,bio_en text,display_order int default 0,created_at timestamptz default now(),updated_at timestamptz default now());
create table contact_settings(id uuid primary key default gen_random_uuid(),phone text,whatsapp text,email text,address text,google_maps_url text,working_days text,working_hours text,updated_at timestamptz default now());
create table footer_settings(id uuid primary key default gen_random_uuid(),footer_description text,copyright_text text,footer_logo text,updated_at timestamptz default now());
create table footer_links(id uuid primary key default gen_random_uuid(),title text not null,url text not null,display_order int default 0,is_active bool default true,created_at timestamptz default now(),updated_at timestamptz default now());
create table social_links(id uuid primary key default gen_random_uuid(),platform text not null,url text not null,display_order int default 0,is_active bool default true,created_at timestamptz default now(),updated_at timestamptz default now());
create table admin_profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,email text,role text default 'admin' check(role in('admin')),created_at timestamptz default now(),updated_at timestamptz default now());
create index on service_subcategories(category_id,display_order);create index on service_content_blocks(subcategory_id,display_order);create index on guidance_articles(category_id,status,published_at);create index on counsellor_profiles(display_order);
create or replace function set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now();return new;end $$;
do $$ declare t text; begin for t in select table_name from information_schema.columns where table_schema='public' and column_name='updated_at' loop
execute format('create trigger trg_upd before update on %I for each row execute function set_updated_at()',t);end loop;end $$;
